<script lang="ts">
  import { DateTime } from "luxon";
  import { t, dateTime, timeOnly } from "../../lib/ui";
  import { formatMinutes } from "../../lib/formatting";
  import { getLiveStatusLabel, getMatchStatusLabel } from "../../lib/session-labels";
  import { filterRowsByTag, deriveHandEntries, eventTypeCounts, handEntryActionLabel } from "../../lib/record-tools";
  import SortableFilterStack from "../../lib/common/SortableFilterStack.svelte";
  import AttendanceFilterPanel from "../../lib/common/AttendanceFilterPanel.svelte";
  import { settings } from "../../lib/stores";
  import StatusBadge from "../../lib/common/StatusBadge.svelte";
  import NameMatchingPanel from "../../lib/NameMatchingPanel.svelte";
  import { statusLabel, statusStyle } from "../../lib/status-style";
  import { getDecisionActionLabel, getParticipantLocationLabel } from "../../lib/session-labels";
  import { groupLabel } from "../../lib/group-label";
  import { toast } from "../../lib/toast";
  import { eventMatchesSearch } from "../../lib/event-search";
  import { busyKeys, runBusy } from "../../lib/busy";
  import TableTooltip from "../../lib/common/TableTooltip.svelte";
  export let view = "status", record: any = {}, state: any = {}, events: any[] = [], users: any[] = [], language = "en", configs: any = {}, mode = "generic", profile: any = null;
  export let onCaptureManual: () => Promise<any> | any = () => {}; export let onCaptureHands: () => Promise<any> | any = () => {};
  export let onDecision: (d: any) => Promise<void> = async () => {}; export let onRevert: (id: string) => Promise<void> = async () => {};
  export let onOverrides: (p?: any) => Promise<boolean | void> = async () => {}; export let onSelectProfile: (id: string) => Promise<boolean | void> = async () => {}; export let onModeChange: (mode: string) => Promise<void> = async () => {};
  export let activeFilter = "";
  export let showSummary = true;
  let search = "", entryType = "", newest = true, ascending = true, filteredRows: any[] = [];
  let stagedLate = "", stagedReturn = "", stagedProfileId = "", settingsError = "", infoEdited = false;
  let selectedEntryTypes: string[] = [];
  let statusTable: HTMLTableElement;
  let columnWidths: number[] = [];
  // Widths are per column position; the Group column only exists in roster mode, so reset on mode change.
  let widthsForRoster: boolean | null = null;
  $: if (rosterMode !== widthsForRoster) { widthsForRoster = rosterMode; columnWidths = []; }
  let resizingColumn = -1, resizeStartX = 0, resizeStartWidth = 0;
  function resizeColumn(index: number, width: number) { const count = statusTable?.querySelectorAll("thead th").length || 8; const next = Array.from({ length: count }, (_, i) => columnWidths[i] || 0); next[index] = Math.max(48, width); columnWidths = next; }
  function startColumnResize(event: MouseEvent, index: number) { event.preventDefault(); resizingColumn = index; resizeStartX = event.clientX; resizeStartWidth = columnWidths[index] || (event.currentTarget as HTMLElement).parentElement?.getBoundingClientRect().width || 80; document.addEventListener("mousemove", handleColumnResize); document.addEventListener("mouseup", stopColumnResize); }
  function handleColumnResize(event: MouseEvent) { if (resizingColumn >= 0) resizeColumn(resizingColumn, resizeStartWidth + event.clientX - resizeStartX); }
  function stopColumnResize() { resizingColumn = -1; document.removeEventListener("mousemove", handleColumnResize); document.removeEventListener("mouseup", stopColumnResize); }
  function handleColumnKey(event: KeyboardEvent, index: number) { if (event.key === "ArrowLeft" || event.key === "ArrowRight") { event.preventDefault(); const th = (event.currentTarget as HTMLElement).parentElement; const current = columnWidths[index] || th?.getBoundingClientRect().width || 80; resizeColumn(index, current + (event.key === "ArrowRight" ? 16 : -16)); } }
  let entryTypesInitialized = false;
  const entryTypeKeys = ["joinedBefore", "join", "leave", "waitingRoomJoinFromOutside", "waitingRoomJoinFromMeeting", "waitingRoomJoinedBefore", "waitingRoomLeave"];
  const tLocal = (zh: string, en: string) => language === "zh-CN" ? zh : en;
  async function captureManualAction() { await runBusy("live-capture-manual", async () => { try { const result = await onCaptureManual(); if (result && typeof result === "object") { const at = DateTime.fromISO(result.timestamp).toFormat("HH:mm:ss"); toast.success(t(`已记录手动考勤名单：${at}，共 ${result.count} 人。`, `Manual snapshot recorded: ${at}, ${result.count} participants.`)); } } catch (error) { toast.error(`${t("捕捉失败：", "Capture failed: ")}${error instanceof Error ? error.message : String(error)}`); } }); }
  async function captureHandsAction() { await runBusy("live-capture-hands", async () => { try { const result = await onCaptureHands(); if (result !== false) toast.success(t("已捕捉举手记录。", "Raise hand records captured.")); } catch (error) { toast.error(`${t("捕捉举手记录失败：", "Failed to capture raise hand records: ")}${error instanceof Error ? error.message : String(error)}`); } }); }
  const statusDefs = [["seen","到过","Seen","seen"],["full_present","全程","Full Present","fullPresent"],["late","迟到","Late","late"],["returned","返回","Returned","returned"],["left_early","早退","Left Early","leftEarly"],["missing","缺席","Absent","missing"],["ignored","不计入","Ignored","ignored"],["total","总计","Total","total"]];
  $: rows = record.rows || [];
  $: duplicateCounts = rows.reduce((counts: Map<string, number>, row: any) => { const name = row.zoomName || ""; if (name) counts.set(name, (counts.get(name) || 0) + 1); return counts; }, new Map<string, number>());
  $: simultaneousDuplicates = [...rows.reduce((counts: Map<string, number>, row: any) => { if (row.isCurrentlyPresent && row.zoomName) counts.set(row.zoomName, (counts.get(row.zoomName) || 0) + 1); return counts; }, new Map<string, number>()).entries()].filter(([name, count]) => name && count > 1).map(([name, count]) => ({ name, count })).sort((a, b) => a.name.localeCompare(b.name, "zh-CN"));
  $: rosterMode = mode === "roster" && (configs.roster || []).length > 0;
  $: statItems = statusDefs.map((d: any) => ({ id:d[0], label:t(d[1],d[2]), color:statusStyle(d[0]).color, count:d[0] === 'total' ? (record.summary?.total ?? rows.length) : (record.summary?.[d[3]] ?? filterRowsByTag(rows,d[0]).length) })).filter((item: any) => item.id === 'total' || item.count > 0);
  $: if (activeFilter && !statItems.some((item: any) => item.id === activeFilter)) activeFilter = '';
  $: movement = record.record?.movementEvents || record.movementEvents || [];
  $: if (!entryTypesInitialized && movement.length) { selectedEntryTypes = [...entryTypeKeys]; entryTypesInitialized = true; }
  $: visibleMovement = movement.filter((e: any) => selectedEntryTypes.includes(e.type || e.eventType) && eventMatchesSearch(e, rows, search)).slice().sort((a: any,b: any) => Date.parse(b.timestamp)-Date.parse(a.timestamp));
  $: counts = eventTypeCounts(movement);
  $: handEntries = deriveHandEntries(events, users);
  $: searchedHands = handEntries.filter((e: any) => eventMatchesSearch(e, rows, search)).slice().sort((a: any,b: any) => Date.parse(b.timestamp)-Date.parse(a.timestamp));
  $: nameChanges = record.record?.nameChangeEvents || record.nameChangeEvents || [];
  $: searchedNameChanges = nameChanges.filter((e: any) => eventMatchesSearch(e, rows, search)).slice().sort((a: any,b: any) => Date.parse(b.timestamp || b.at)-Date.parse(a.timestamp || a.at));
  $: pendingDecisions = (state.reconciliationDecisions || []).slice().reverse();
  $: settingsProfile = profile || (configs.profiles || []).find((p: any) => p.id === (state.selectedProfileId || record.record?.selectedProfileId)) || (configs.profiles || []).find((p: any) => p.id === "default-all");
  $: meetingStart = record.record?.startedAt || record.meeting?.startedAt || record.startedAt;
  $: startTime = meetingStart ? DateTime.fromISO(meetingStart).toFormat("HH:mm") : "";
  $: effectiveLate = Number(state.lateAfterMinutesOverride ?? record.record?.lateAfterMinutes ?? settingsProfile?.lateAfterMinutes ?? 0);
  $: effectiveReturn = Number(state.returnWindowMinutesOverride ?? record.record?.returnWindowMinutes ?? settingsProfile?.returnWindowMinutes ?? 8);
  $: lateTime = meetingStart ? DateTime.fromISO(meetingStart).plus({ minutes: Number(stagedLate || 0) }).toFormat("HH:mm") : "--:--";
  // The form follows the saved settings (which may load after first render) until the user edits it.
  $: sourceProfileId = state.selectedProfileId || record.record?.selectedProfileId || settingsProfile?.id || "default-all";
  $: sourceLate = String(state.lateAfterMinutesOverride ?? record.record?.lateAfterMinutes ?? settingsProfile?.lateAfterMinutes ?? 10);
  $: sourceReturn = String(state.returnWindowMinutesOverride ?? record.record?.returnWindowMinutes ?? settingsProfile?.returnWindowMinutes ?? 8);
  $: if (!infoEdited) { stagedProfileId = sourceProfileId; stagedLate = sourceLate; stagedReturn = sourceReturn; }
  $: hasOverrides = state.lateAfterMinutesOverride != null || state.returnWindowMinutesOverride != null;
  $: currentMode = (state.mode || mode) === "roster" ? t("花名册", "Roster") : t("普通模式", "Generic");
  $: lateRule = Number(stagedLate) < 0
    ? t("在会议开始前 {0} 分钟（{1}）之后到会，将记为迟到。", "Arriving after {1}, {0} minutes before the meeting starts, will count as late.").replace("{0}", String(Math.abs(Number(stagedLate)))).replace("{1}", lateTime)
    : t("在 {1} 之后到会，将记为迟到（从会议开始后 {0} 分钟算起）。", "Arriving after {1} will count as late ({0} minutes after the meeting starts).").replace("{0}", String(stagedLate)).replace("{1}", lateTime);
  async function applyInfoSettings() {
    const late = Number(stagedLate), ret = Number(stagedReturn);
    if (!Number.isFinite(late) || late < -60 || late > 120) { settingsError = t("迟到阈值范围为 −60 至 120 分钟", "Late override must be between −60 and 120 minutes"); return; }
    if (!Number.isInteger(ret) || ret < 1 || ret > 60) { settingsError = t("返回窗口范围为 1 至 60 分钟", "Return window must be 1 to 60 minutes"); return; }
    settingsError = "";
    await runBusy("live-info-settings", async () => { try {
      if (stagedProfileId !== (state.selectedProfileId || record.record?.selectedProfileId || "default-all") && (await onSelectProfile(stagedProfileId)) === false) throw Error(t("数据已被修改，请重试", "Data changed; please retry"));
      // Only values that differ from the selected profile are overrides.
      const chosen = (configs.profiles || []).find((p: any) => p.id === stagedProfileId);
      const saved = await onOverrides({ lateAfterMinutesOverride: chosen && Number(chosen.lateAfterMinutes) === late ? null : late, returnWindowMinutesOverride: chosen && Number(chosen.returnWindowMinutes) === ret ? null : ret });
      if (saved === false) throw Error(t("数据已被修改，请重试", "Data changed; please retry"));
      infoEdited = false;
      toast.success(t("设置已应用", "Settings applied"));
    } catch (error) { toast.error(`${t("保存失败：", "Save failed: ")}${error instanceof Error ? error.message : String(error)}`); } });
  }
  async function restoreDefault() {
    await runBusy("live-info-settings", async () => { try { if ((await onSelectProfile("default-all")) === false) throw Error(t("数据已被修改，请重试", "Data changed; please retry")); infoEdited = false; stagedProfileId = "default-all"; stagedLate = String((configs.profiles || []).find((p: any) => p.id === "default-all")?.lateAfterMinutes ?? 0); stagedReturn = String((configs.profiles || []).find((p: any) => p.id === "default-all")?.returnWindowMinutes ?? 8); toast.info(t("已切换到默认配置", "Switched to default profile")); }
    catch (error) { toast.error(`${t("保存失败：", "Save failed: ")}${error instanceof Error ? error.message : String(error)}`); } });
  }
  function changeInfoProfile(id: string) { infoEdited = true; stagedProfileId = id; const selected = (configs.profiles || []).find((p: any) => p.id === id); if (selected) { stagedLate = String(selected.lateAfterMinutes); stagedReturn = String(selected.returnWindowMinutes); } }
  function statusTone(status: string) { return status === "fullPresent" || status === "present" || status === "inMeeting" ? "success" : status === "late" || status === "returnedAfterLongAbsence" ? "warning" : status === "missing" || status === "leftEarly" ? "danger" : "neutral"; }
  const tagPriority = ["left_early", "late", "returned", "full_present", "seen", "missing", "ignored", "guest", "unmatched"];
  function rowStatusTags(row: any) {
    const tags = [...new Set<string>(row.tags || [])].filter((tag) => !["ignored", "guest", "unmatched"].includes(tag));
    if (tags.includes("full_present")) return tags.filter((tag) => tag !== "seen").sort((a, b) => tagPriority.indexOf(a) - tagPriority.indexOf(b));
    return tags.sort((a, b) => tagPriority.indexOf(a) - tagPriority.indexOf(b));
  }
  function duplicateName(row: any) { const name = row.zoomName || row.canonicalName || "—"; if ((duplicateCounts.get(row.zoomName) || 0) > 1 && row.participantUUID) { const compact = String(row.participantUUID).replace(/[^a-zA-Z0-9]/g, "").toLowerCase(); return `${name} · ${compact.slice(-4) || String(row.participantUUID).slice(-4).toLowerCase()}`; } return row.zoomNames?.join(" / ") || name; }

  function movementLabel(type: string) { const labels: Record<string, [string,string]> = { join:["加入会议","Joined"],leave:["离开会议","Left"],joinedBefore:["启动时已在会议中","Present at start"],waitingRoomJoinFromOutside:["进入等候室","Entered waiting room"],waitingRoomJoinFromMeeting:["移至等候室","Moved to waiting room"],waitingRoomJoinedBefore:["启动时在等候室","Waiting at start"],waitingRoomLeave:["离开等候室","Left waiting room"] }; const pair=labels[type]; return pair ? t(pair[0],pair[1]) : t("未知","Unknown"); }
</script>

{#if view === "status"}
  <section class="status-view">
    {#if showSummary}<div class="summary-row"><SortableFilterStack items={statItems} active={activeFilter} onSelect={(id) => activeFilter = activeFilter === id ? '' : id} /><div class="mode-switch" aria-label={t("考勤模式", "Attendance mode")}><button class:chosen={mode === 'generic'} onclick={() => onModeChange('generic')}>{t("普通模式", "Generic")}</button><button class:chosen={mode === 'roster'} onclick={() => onModeChange('roster')}>{t("花名册", "Roster")}</button></div></div>{/if}
    <AttendanceFilterPanel rows={rows} roster={configs.roster || []} configGroups={[]} profile={settingsProfile} {mode} {language} initiallyOpen={!$settings.filterDefaultsClosed} {activeFilter} bind:ascending onActiveFilterChange={(value) => activeFilter = value} onRows={(value) => filteredRows = value} />
    {#if simultaneousDuplicates.length}<div class="duplicate-warning"><strong>{t("⚠ 重复姓名：", "⚠ Duplicate names:")}</strong><span>{simultaneousDuplicates.map((duplicate) => `${duplicate.name} (${duplicate.count}${t("人", " people")})`).join("、")}</span><span class="duplicate-note">{t("检测到同名参与者，考勤匹配可能不准确。", "Duplicate names detected. Attendance matching may be inaccurate.")}</span></div>{/if}
    <div class="table-wrap"><table bind:this={statusTable} class="attendance-table" style:table-layout={columnWidths.length ? "fixed" : "auto"}><thead><tr>{#each ["#", rosterMode ? t("姓名", "Name") : t("Zoom 名称", "Zoom Name"), t("状态", "Status"), t("位置", "Location"), ...(rosterMode ? [t("分组", "Group")] : []), t("首次加入", "First join"), t("最后进入/退出", "Last entry/exit"), t("在线分钟", "Minutes Present")] as heading, i}<th style:width={columnWidths[i] ? `${columnWidths[i]}px` : undefined} class:th-resizable={true}>{heading}<!-- svelte-ignore a11y_no_noninteractive_tabindex a11y_no_noninteractive_element_interactions --><span class="th-resize-handle" role="separator" aria-label={t("调整列宽", "Resize column")} aria-orientation="vertical" tabindex="0" onmousedown={(event) => startColumnResize(event, i)} onkeydown={(event) => handleColumnKey(event, i)}></span></th>{/each}</tr></thead><tbody>{#each filteredRows as r, i}<tr class={`status-${r.currentStatus}`}><td>{i+1}</td><td class="participant-name">{#if rosterMode}{#if r.isExpected === false}<span role="img" aria-label={t("范围外参会者", "Unexpected roster participant")} title={t("⚠️ 范围外参会者：此成员已匹配到花名册，但其分组不在当前考勤配置的包含范围内。", "⚠️ Unexpected participant: matched to the roster, but their group is outside the current attendance profile.")}>⚠️</span>{/if}<b>{r.canonicalName || t("未匹配", "Unmatched")}</b>{#if r.zoomName && r.canonicalName && r.zoomName !== r.canonicalName} ({r.zoomName}){/if}{#if r.sharedName}<small>{t("疑似重名或共用账号名", "Possible Duplicate or Shared Name")}</small>{/if}{:else}<b>{duplicateName(r)}</b>{/if}</td><td><div class="badges">{#each rowStatusTags(r) as tag}<StatusBadge status={tag} label={statusLabel(tag, language)} />{/each}{#if r.matchStatus === "unmatched" || r.matchStatus === "guest"}<StatusBadge label={getMatchStatusLabel(r.matchStatus, language as any)} />{/if}</div></td><td>{#if r.currentLocation === "waiting-room"}<span class="waiting-pill">{getParticipantLocationLabel(r.currentLocation, language as any)}</span>{:else}{getParticipantLocationLabel(r.currentLocation, language as any) || "—"}{/if}</td>{#if rosterMode}<td class="group-cell" title={groupLabel(r.group, language)}>{groupLabel(r.group, language)}</td>{/if}<td>{(r.firstJoinAt ? timeOnly(r.firstJoinAt) : "—")}</td><td>{(r.lastSeenAt ? timeOnly(r.lastSeenAt) : "—")}</td><td>{Math.round(r.totalPresenceMinutes || 0)}</td></tr>{:else}<tr><td colspan={rosterMode ? 8 : 7} class="empty">{t("等待参与者事件…", "Waiting for participant events…")}</td></tr>{/each}</tbody></table><TableTooltip targetTable={statusTable} /></div>
  </section>
{:else if view === "matching"}
  <NameMatchingPanel rows={rows} decisions={state.reconciliationDecisions || []} roster={configs.roster || []} aliases={configs.aliases || []} nameChanges={record.record?.nameChangeEvents || []} language={language} {onDecision} {onRevert} />
  {:else if view === "names"}
  <section class="log-view"><h2>{t("名称变更", "Name Changes")} <small>{nameChanges.length}</small></h2><p class="description">{t("记录参与者在会议期间更改的名称。", "Tracks participant name changes during the meeting.")}</p><div class="event-filters"><input placeholder={t("旧名、新名或拼音", "Old/new name or pinyin")} bind:value={search}/></div>{#if searchedNameChanges.length}<div class="table-wrap"><table><thead><tr><th>{t("时间","Time")}</th><th>{t("旧名称","Previous Name")}</th><th>{t("新名称","New Name")}</th></tr></thead><tbody>{#each searchedNameChanges as item}<tr><td>{timeOnly(item.timestamp || item.at)}</td><td>{item.previousScreenName || item.previous_screen_name || "—"}</td><td>{item.nextScreenName || item.next_screen_name || "—"}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">{nameChanges.length ? t("没有符合搜索条件的名称变更。", "No name changes match your search.") : t("暂无名称变更记录。", "No name changes recorded yet.")}</p>{/if}</section>
{:else if view === "info"}
  <section class="settings-view">
    <div class="setting-cards">
      <article><small>{t("考勤记录号", "Record ID")}</small><b>{record.record?.meetingInstanceId || record.record?.instanceId || record.meeting?.instanceId || record.instanceId || "—"}</b></article>
      <article><small>{t("当前模式", "Current Mode")}</small><b>{currentMode}</b></article>
      <article><small>{t("会议号", "Meeting number")}</small><b>{record.meeting?.meetingNumber || record.record?.meetingNumber || record.meetingNumber || "—"}</b></article>
      <article><small>{t("开始时间", "Start time")}</small><b>{meetingStart ? dateTime(meetingStart) : "—"}</b></article>
    </div>
    <h2>{t("自动考勤设置", "Auto Attendance Settings")}</h2>
    <div class="info-form">
      <label>{t("考勤配置", "Attendance Profile")}<select value={stagedProfileId} onchange={(e) => changeInfoProfile(e.currentTarget.value)}>{#each (configs.profiles || []).filter((p: any) => p.active) as p}<option value={p.id}>{p.name}</option>{/each}</select><small>{t("切换配置时，会同时更新迟到和返回设置。", "Changing the profile also updates the late and return settings.")}</small></label>
      <label>{t("迟到判定", "Late Rule")}<input type="number" min="-60" max="120" bind:value={stagedLate} oninput={() => infoEdited = true} /><small>{lateRule}</small></label>
      <label>{t("返回判定", "Return Rule")}<input type="number" min="1" max="60" bind:value={stagedReturn} oninput={() => infoEdited = true} /><small>{t("离开会议 {0} 分钟或更久后再回来，会显示为\"返回\"。", "Leaving for {0} minutes or longer and then coming back will show a \"Returned\" status.").replace("{0}", stagedReturn)}</small></label>
      {#if !hasOverrides}<small>{t("（使用已保存的设置）", "(using saved settings)")}</small>{/if}
      {#if settingsError}<small class="settings-error">{settingsError}</small>{/if}
      <div class="profile-actions"><button class="primary" disabled={$busyKeys.has("live-info-settings")} onclick={applyInfoSettings}>{t("应用", "Apply")}</button><button disabled={$busyKeys.has("live-info-settings")} onclick={restoreDefault}>{t("恢复默认配置", "Restore Default")}</button></div>
    </div>
  </section>{:else if view === "manual"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("手动考勤记录", "Manual Attendance")}</h2><p>{t("捕捉并查看当前参与者列表。", "Capture and review the current participant list.")}</p></div><button class="primary" disabled={$busyKeys.has("live-capture-manual")} onclick={captureManualAction}>{$busyKeys.has("live-capture-manual") ? t("捕捉中…", "Capturing…") : t("捕捉当前名单", "Capture Attendance")}</button></div><p class="subheading">{t("已捕捉", "Captured")} {state.manualSnapshots?.length || 0} {t("次", "times")}</p>{#each [...(state.manualSnapshots || [])].reverse() as snapshot, si}<details class="snapshot" open={si === 0}><summary><b>{dateTime(snapshot.timestamp)}</b><span>{t("共", "Total")} {snapshot.participants?.length || 0} {t("位参与者", "participants")}</span></summary><div class="table-wrap"><table><thead><tr><th>#</th><th>{t("姓名", "Name")}</th><th>{t("参与者 ID", "Participant ID")}</th><th>{t("位置", "Location")}</th><th>{t("匹配状态", "Match Status")}</th></tr></thead><tbody>{#each snapshot.participants || [] as p, i}<tr><td>{i+1}</td><td>{p.screenName || "—"}</td><td>{p.participantUUID || p.sessionParticipantId || "—"}</td><td>{getParticipantLocationLabel(p.location, language as any) || "—"}</td><td>{getMatchStatusLabel(p.matchStatus, language as any)}</td></tr>{/each}</tbody></table></div></details>{:else}<p class="empty">{t("尚无手动考勤记录", "No manual attendance records yet")}</p>{/each}</section>
{:else if view === "entry"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("进出记录", "Entry/Exit Logs")} <small>{movement.length}</small></h2><p>{t("查看参与者进入、离开和等候室事件。", "Review join, leave, and waiting room events.")}</p></div></div><div class="event-filters"><input aria-label={t("搜索名称", "Search names")} placeholder={t("搜索姓名或拼音…", "Search by name or pinyin…")} bind:value={search} /><button onclick={() => { search = ""; selectedEntryTypes = [...entryTypeKeys]; }}>{t("清除筛选", "Clear Filters")}</button></div><div class="filter-chips">{#each entryTypeKeys as type}<button class:active={selectedEntryTypes.includes(type)} aria-pressed={selectedEntryTypes.includes(type)} onclick={() => selectedEntryTypes = selectedEntryTypes.includes(type) ? selectedEntryTypes.filter((v) => v !== type) : [...selectedEntryTypes, type]}>{movementLabel(type)} · {counts[type] || 0}</button>{/each}</div>{#if visibleMovement.length}<div class="table-wrap"><table><thead><tr><th>{t("时间","Time")}</th><th>{t("姓名","Name")}</th><th>{t("事件类型","Event type")}</th></tr></thead><tbody>{#each visibleMovement as event}<tr><td>{timeOnly(event.timestamp)}</td><td><b>{event.participant?.screenName || "—"}</b></td><td><StatusBadge label={movementLabel(event.type || event.eventType)} tone={(event.type || "").toLowerCase().includes("leave") ? "warning" : "success"} /></td></tr>{/each}</tbody></table></div>{:else}<p class="empty">{movement.length ? t("没有符合筛选条件的事件。", "No matching events.") : t("暂无事件记录。", "No events recorded yet.")}</p>{/if}</section>
{:else if view === "hands"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("举手跟踪", "Raise Hand")}</h2><p>{t("查看举手事件并捕捉当前举手名单。", "Review hand events and capture the current raised hands.")}</p></div><button class="primary" disabled={!users.some((u: any) => u.raisedHand || u.raised_hand) || $busyKeys.has("live-capture-hands")} onclick={captureHandsAction}>{t("捕捉举手记录", "Capture Raise Hand Records")}</button></div><div class="hand-current"><h3>{t("当前举手", "Current Hand Raises")} <small>{users.filter((u: any) => u.raisedHand || u.raised_hand).length} {t("人", "people")}</small></h3><div class="hand-chips">{#each users.filter((u: any) => u.raisedHand || u.raised_hand) as user}<StatusBadge label={user.name || "—"} tone="success" />{:else}<span class="muted">{t("目前没有举手", "No hands raised right now")}</span>{/each}</div></div><div class="event-filters"><input placeholder={t("搜索姓名或拼音…", "Search by name or pinyin…")} bind:value={search} /><span>{searchedHands.length} {t("条记录", "records")}</span></div><div class="table-wrap"><table><thead><tr><th>{t("时间", "Time")}</th><th>{t("姓名", "Name")}</th><th>{t("状态", "Status")}</th></tr></thead><tbody>{#each searchedHands as event}<tr><td>{timeOnly(event.timestamp)}</td><td><b>{event.screenName}</b></td><td><StatusBadge label={handEntryActionLabel(event, language)} tone={event.action === "raise" ? "success" : "neutral"} /></td></tr>{:else}<tr><td colspan="3" class="empty">{t("没有举手事件", "No raise-hand events")}</td></tr>{/each}</tbody></table></div><h3 class="section-heading">{t("举手记录快照", "Raise Hand Captures")}</h3>{#each [...(state.raiseHandCaptures || [])].reverse() as capture}<article class="event-row"><time>{dateTime(capture.timestamp)}</time><b>{capture.totalCount} {t("人", "people")}</b><span>{(capture.screenNames || []).join(", ")}</span></article>{:else}<p class="empty">{t("尚无举手快照", "No raise-hand captures yet")}</p>{/each}</section>
{:else if view === "operations"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("操作面板", "Operations")}</h2><p>{t("查看本场会议的匹配与协调决定。", "Review matching and reconciliation decisions for this meeting.")}</p></div></div><div class="event-filters"><span>{t("已记录决定", "Recorded decisions")} · {pendingDecisions.length}</span><button disabled={$busyKeys.has("live-capture-manual")} onclick={captureManualAction}>{t("捕捉当前名单", "Capture current list")}</button><button disabled={!users.some((u: any) => u.raisedHand || u.raised_hand) || $busyKeys.has("live-capture-hands")} onclick={captureHandsAction}>{t("捕捉举手", "Capture Raised Hands")}</button></div>{#each pendingDecisions as decision}<article class="event-row"><time>{dateTime(decision.createdAt)}</time><b>{decision.zoomName || "—"}</b><StatusBadge label={getDecisionActionLabel(decision.action, language as any)} /><span>{decision.canonicalName || ""}</span></article>{:else}<p class="empty">{t("尚无协调决定", "No reconciliation decisions yet")}</p>{/each}</section>
{/if}

<style>
 .status-view,.log-view,.settings-view{min-width:0}.event-filters,.view-heading,.profile-actions{display:flex;align-items:center;gap:8px;margin:8px 0}.event-filters input{min-height:30px!important;padding:6px 9px!important;flex:1}.event-filters span{font-size:10px;color:var(--muted);white-space:nowrap}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:7px;background:#fff}table{width:100%;border-collapse:collapse;font-size:11px;text-align:left}th{position:sticky;top:0;background:#f4f6fa;color:#596273;font-size:10px;text-transform:uppercase;letter-spacing:.35px}th,td{padding:7px 9px;border-bottom:1px solid var(--line);white-space:nowrap}td{height:36px}.attendance-table{table-layout:fixed}.attendance-table th,.attendance-table td{overflow:hidden;text-overflow:ellipsis}.attendance-table th{position:relative;padding-right:14px}.th-resize-handle{position:absolute;top:0;right:0;width:7px;height:100%;cursor:col-resize;touch-action:none}.th-resize-handle:hover,.th-resize-handle:focus-visible{background:#9bbaf5;outline:0}.attendance-table .group-cell{max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.attendance-table .participant-name{max-width:260px;white-space:normal;overflow-wrap:anywhere}.attendance-table .participant-name b,.attendance-table .participant-name small{overflow-wrap:anywhere}tbody tr:last-child td{border-bottom:0}tbody tr.status-missing{opacity:.55}tbody tr.status-missing td{font-style:italic}tbody tr.status-late{background:color-mix(in srgb,#fffbeb 50%,white)}tbody tr.status-leftEarly{background:color-mix(in srgb,#fef2f2 50%,white)}tbody tr.status-returnedAfterLongAbsence{background:color-mix(in srgb,#ecfeff 50%,white)}tbody tr.status-guest,tbody tr.status-unmatched{background:#f5f5f9}td b{font-weight:700}td small{display:block;color:var(--muted);font-size:9px}.duplicate-warning{display:flex;gap:6px;flex-wrap:wrap;padding:9px 11px;margin:8px 0;border:1px solid #fed7aa;border-radius:7px;background:#fffbeb;color:#9a3412;font-size:11px}.duplicate-note{flex-basis:100%;color:#7c2d12}.waiting-pill{display:inline-block;padding:2px 7px;border-radius:999px;background:#edf1f5;color:#596273;font-size:10px}.badges{display:flex;gap:4px}.empty{text-align:center;color:var(--muted);padding:22px}.log-view h2,.settings-view h2{font-size:14px;margin:10px 0 4px}.log-view h2 small{font-size:10px;color:var(--muted);font-weight:400}.view-heading{justify-content:space-between;align-items:center}.view-heading h2{margin:0}.view-heading p{margin:4px 0;color:var(--muted);font-size:11px}.view-heading button{min-height:30px}.subheading{font-size:11px;color:var(--muted);margin:10px 0}.snapshot{border:1px solid var(--line);border-radius:7px;margin:8px 0;background:white}.snapshot summary{display:flex;gap:14px;align-items:center;cursor:pointer;padding:10px;font-size:11px}.snapshot summary span{color:var(--muted)}.event-row{display:flex;align-items:center;gap:10px;min-height:34px;padding:6px 8px;border-bottom:1px solid var(--line);font-size:11px}.event-row:last-child{border-bottom:0}.event-row time{min-width:145px;color:var(--muted);font-size:10px}.event-row span:last-child{margin-left:auto}.setting-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin:10px 0}.setting-cards article{display:grid;gap:5px;padding:9px;border:1px solid var(--line);border-radius:7px;background:white;min-width:0}.setting-cards small{font-size:9px;color:var(--muted)}.setting-cards b{font-size:11px;overflow-wrap:anywhere}.hand-current{padding:10px 0;border-bottom:1px solid var(--line)}.hand-current h3,.section-heading{font-size:12px;margin:0 0 8px}.hand-current h3 small{margin-left:5px;color:var(--muted);font-weight:400}.hand-chips{display:flex;gap:6px;flex-wrap:wrap}.muted{font-size:11px;color:var(--muted)}.info-form{display:grid;gap:10px;padding:10px;border:1px solid var(--line);border-radius:7px;background:white}.info-form label{display:grid;gap:5px;font-size:11px;color:var(--muted)}.info-form input,.info-form select{max-width:300px;min-height:30px;padding:5px 7px}.info-form small{font-size:10px;color:var(--muted);line-height:1.5}.info-form .settings-error{color:#b42318}.filter-chips{display:flex;gap:6px;flex-wrap:wrap;margin:6px 0 9px}.filter-chips button{min-height:26px;padding:4px 8px;border:1px solid var(--line);border-radius:16px;background:#fff;color:#596273;font-size:10px}.filter-chips button.active{border-color:#aac4f5;background:#edf4ff;color:#245caa}.description{font-size:11px;color:var(--muted);margin:4px 0 8px}
 @media(max-width:900px){.setting-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.event-row{flex-wrap:wrap}.event-row time{min-width:110px}}
</style>
